import java.util.Scanner;

public class Main {
    static int total_n, total_k, total_p;
    static int[][] memo;
    static int[] fact, inv_fact;

    static int power_mod(int base, int exp) {
        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % total_p;
            }
            b = (b * b) % total_p;
            exp >>= 1;
        }
        return (int) res;
    }

    static int get_lowbit_value(int x) {
        return x & (-x);
    }

    static int recursive_solve(int current, int S) {
        if (memo[current][S] != -1) return memo[current][S];
        if (S == 0) {
            long res = fact[total_n];
            for (int i = 1; i <= current; i++) {
                res = (res * (total_k - i + 1)) % total_p;
            }
            memo[current][S] = (int) res;
            return memo[current][S];
        }
        long sum = 0;
        int U = S - get_lowbit_value(S);
        for (int T = U; T != 0; T = (T - 1) & U) {
            long temp = ((long) inv_fact[S - T] * recursive_solve(current + 1, T)) % total_p;
            sum = (sum + temp) % total_p;
        }
        long temp = ((long) inv_fact[S] * recursive_solve(current + 1, 0)) % total_p;
        sum = (sum + temp) % total_p;
        memo[current][S] = (int) sum;
        return memo[current][S];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_n = sc.nextInt();
        total_k = sc.nextInt();
        total_p = sc.nextInt();

        int result = 1;
        for (int i = 1; i <= total_n; i++) {
            result = (int) ((long) result * total_k % total_p);
        }

        if (total_n % 2 == 0) {
            setup();
            int maxS = total_n;
            memo = new int[26][250010];
            for (int i = 0; i < 26; i++) {
                for (int j = 0; j <= maxS; j++) {
                    memo[i][j] = -1;
                }
            }
            result = (result - recursive_solve(0, total_n) + total_p) % total_p;
        }

        System.out.println(result);
        sc.close();
    }

    static void setup() {
        fact = new int[250010];
        inv_fact = new int[250010];
        fact[0] = 1;
        for (int i = 1; i <= total_n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % total_p);
        }
        inv_fact[total_n] = power_mod(fact[total_n], total_p - 2);
        for (int i = total_n; i >= 1; i--) {
            inv_fact[i - 1] = (int) ((long) inv_fact[i] * i % total_p);
        }
    }
